52	/// A registered endpoint whose exact callable instance is ready for use.
53	///
54	/// Dropping this handle does not stop the endpoint. Call [`shutdown`](Self::shutdown)
55	/// for scoped endpoint lifetimes, or [`wait`](Self::wait) for the traditional
56	/// runtime-owned lifetime.
57	pub struct StartedEndpoint {
58	    instance: Instance,
59	    shutdown_token: CancellationToken,
60	    task: tokio::task::JoinHandle<anyhow::Result<()>>,
61	}
